import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {extract,ids} from './build-full-recipes.mjs';
const manifest=JSON.parse(await fs.readFile(new URL('../tests/sandcastle/full-recipes.json',import.meta.url),'utf8'));
assert.deepEqual(manifest.cases.map(c=>c.id),ids);
for(const c of manifest.cases){const expected=await extract(c.id);const actual=JSON.parse(await fs.readFile(new URL(`../tests/sandcastle/full/${c.id}.json`,import.meta.url),'utf8'));assert.deepEqual(actual,expected.entities);assert.equal(c.sourceSha256,expected.manifest.sourceSha256);assert.equal(c.htmlSha256,expected.manifest.htmlSha256);assert.equal(c.assetSha256,expected.manifest.assetSha256);assert.equal(c.entityCount,actual.length);assert.equal(c.framing,expected.manifest.framing);if(c.format==='czml'){const raw=JSON.parse(await fs.readFile(new URL(`../tests/sandcastle/full/${c.id}.czml`,import.meta.url),'utf8'));assert.deepEqual(raw,expected.czml);}if(c.format==='primitives'){assert.deepEqual(JSON.parse(await fs.readFile(new URL(`../tests/sandcastle/full/${c.id}.primitive.json`,import.meta.url),'utf8')),expected.primitive);if(c.id.includes('outline')||c.id==='simple-polyline-dev')assert(actual.every(e=>!e.fill&&e.outline));else if(c.id.includes('offset')||c.id==='frustum-dev')assert(actual.some(e=>e.fill&&!e.outline)&&actual.some(e=>!e.fill&&e.outline));else assert(actual.every(e=>e.fill&&!e.outline&&(e.surfaceAppearance||e.material||e.shape.type==='widePolyline')));}assert(actual.length>0||c.format==='scene');if(c.format==='scene')assert.deepEqual(JSON.parse(await fs.readFile(new URL(`../tests/sandcastle/full/${c.id}.scene.json`,import.meta.url),'utf8')),expected.scene);if(c.format==='groups')assert.deepEqual(JSON.parse(await fs.readFile(new URL(`../tests/sandcastle/full/${c.id}.groups.json`,import.meta.url),'utf8')),expected.grouped);if(c.format==='variants')assert.deepEqual(JSON.parse(await fs.readFile(new URL(`../tests/sandcastle/full/${c.id}.variants.json`,import.meta.url),'utf8')),expected.variants);assert(c.requirements.length>0);}
const plane=JSON.parse(await fs.readFile(new URL('../tests/sandcastle/full/plane.json',import.meta.url),'utf8'));assert.deepEqual(plane.map(e=>e.shape.normal),[[1,0,0],[0,1,0],[0,0,1]]);
console.log(`Full recipes passed: all statements of ${manifest.cases.length} pinned sources executed; fixtures match every entity, plane basis, material, alpha, fill/outline and collection framing`);

